<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Comprovante A4 · Requisição #{{ $fuelRequest->request_number }}</title><style>@page{size:A4 portrait;margin:8mm}*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;color:#152d25;font-size:9px}.sheet{width:100%}.copy{height:134mm;padding:5mm 6mm;border:1px solid #17354f;page-break-inside:avoid;overflow:hidden}.copy+.copy{margin-top:4mm;border-top:2px dashed #17354f}.brand{display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:2px solid #b78c42;padding-bottom:4mm}.brand img{width:42mm;height:auto}.brand-copy{text-align:right}.brand-copy h1{margin:0;color:#17354f;font-size:17px}.brand-copy p{margin:3px 0 0;color:#52615a;font-size:8px}.via{display:inline-block;margin-top:4px;padding:3px 6px;background:#17354f;color:#fff;font-weight:700;text-transform:uppercase;letter-spacing:.08em}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px 10px;margin:5mm 0}.field{padding:4px 0;border-bottom:1px solid #d7ddd7}.field span{display:block;color:#68736c;font-size:7px;font-weight:700;text-transform:uppercase;letter-spacing:.06em}.field strong{display:block;margin-top:2px;font-size:9px}.section-title{margin:4mm 0 2mm;padding:3px 5px;background:#edf3ef;color:#17354f;font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.06em}.notice{padding:4px 5px;background:#fff7e5;border-left:3px solid #b78c42;color:#604d22}.signatures{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24mm;margin-top:7mm}.signature{padding-top:7mm;border-top:1px solid #17354f;text-align:center;font-size:8px}.footer{margin-top:3mm;color:#68736c;font-size:7px;text-align:center}@media screen{body{padding:10mm;background:#697076}.sheet{max-width:194mm;margin:0 auto;background:#fff;box-shadow:0 0 8px rgba(0,0,0,.35)}.copy{height:134mm}}@media print{body{background:#fff}.sheet{width:100%}}</style></head><body><main class="sheet">@php($copies=[['Via da